    private function via(string $transport): TungoClient
    {
        return match ($transport) {
            'guzzle' => $this->client(httpClient: new GuzzleClient()),
            'guzzle-curl' => $this->client(httpClient: new GuzzleClient(['handler' => HandlerStack::create(new CurlHandler())])),
            'guzzle-multi' => $this->client(httpClient: new GuzzleClient(['handler' => HandlerStack::create(new CurlMultiHandler())])),
            'guzzle-forced' => $this->client(transport: new GuzzleTransport(new GuzzleClient(), curlHandler: true)),
            default => $this->client(),
        };
    }

    private function assertServerSawTheClientLeave(): void
    {
        $deadline = microtime(true) + 3.0;
        do {
            $requests = $this->requests();
            if ($requests !== [] && $requests[0]['client_gone']) {
                $this->addToAssertionCount(1);

                return;
            }
            usleep(20000);
        } while (microtime(true) < $deadline);
        self::fail('the connection was still open three seconds after the stream was abandoned');
    }

    private static function text(string $delta): string
    {
        return "event: text\ndata: " . self::json(['type' => 'text', 'delta' => $delta]) . "\n\n";
    }

    private static function done(): string
    {
        return "event: done\ndata: {\"type\":\"done\",\"stop_reason\":\"end_turn\"}\n\n";
    }

