    #[DataProvider('pushTransports')]
    public function testAnAbandonedStreamIsClosedByTheNextRequestAtTheLatest(string $transport): void
    {
        $this->enqueue(
            ['status' => 200, 'headers' => self::HEADERS, 'chunks' => [['data' => self::text('раз')], ['delay_ms' => 20000, 'data' => self::done()]]],
            ['status' => 200, 'json' => self::sample('companies.list')],
        );
        $client = $this->via($transport);
        $started = microtime(true);
        foreach ($client->chat->createStream(new ChatMessageRequest(message: 'q')) as $event) {
            break;
        }
        unset($event);
        // Nothing blocks, whatever the PHP version, and the next call of the client leaves no stream behind.
        self::assertNotEmpty($client->companies->list()->data);
        self::assertLessThan(3.0, microtime(true) - $started);
        $this->assertServerSawTheClientLeave();
    }
